import {artifactShopMarkup} from './campaign-ui.js?v=20261111b';
import {hasRisk,RISK,healingLeft,healingAmount,healingNote,soundLoss} from './risk-rules.js?v=20261111b';
import {hasGimmicks,STAGE_GIMMICK_PLANS} from './dungeon-gimmicks.js?v=20261111b';
import {keyOfferMarkup} from './gimmick-presentation.js?v=20261111b';
import {CARDS,stageOffers,echoFadeEvery} from './engine.js?v=20261111b';
import {STAGES,stageIndex,checkpointIndex} from './expedition-stages.js?v=20261111b';
import {abilityEffectsMarkup,abilityNotesMarkup} from './ability-guide.js?v=20261111b';
import {tokenMarkup,itemMarkup} from './token-art.js?v=20261111b';
import {memoryLore} from './merchant-story.js?v=20261111b';
const poolSize=s=>s.deck.length+s.discard.length+s.played.length;
const choiceName={recruit:'새 기억 영입',refine:'기억 정리',resupply:'보급 확보'};
const quotes=['심층의 기억을 찾는 손님이라… 네 손만으로는 멀지. 함께 갈 솜씨를 고르렴.','많이 쥐는 것만이 답은 아니야. 내려놓아야 제때 돌아오는 기억도 있거든.','이 아래엔 네 이야기를 끝내려는 것이 있어. 갈 힘과 돌아올 힘을 같이 챙겨.'];
export function stageTrackMarkup(s){return `<span class="stage-track">${STAGES.map((stage,i)=>`<span class="${i===stageIndex(s)?'current':''}" style="--stage-color:${stage.color}">${stage.name}</span>${i<3?'<i>›</i>':''}`).join('')}</span>`;}
export function stageCampMarkup(s,recruit=false){
 const index=checkpointIndex(s),stage=STAGES[index],ready=s.stagePrepared[index]!==null;
 const quote=hasGimmicks(s)?['수정고에 남은 열쇠를 가져가도 좋아. 다만 수정이 울리는 동안은 발이 묶여. 경비 통로로 곧장 갈 거라면 칼을 챙기렴.','수로의 쇠판은 발소리를 기억해. 낙하구로 내려간 손님은 사다리를 열고 돌아오더구나. 돌아올 길까지 골랐니?','아래의 문은 부서진 봉인병의 핵에 반응하지. 제단의 기억과 호흡을 맞춰도 열려. 네 주머니엔 어느 솜씨가 있니?'][index]:quotes[index];
 const riskNote=hasRisk(s)?`<p class="risk-rule-note">${healingNote(s)}. 메달·보급·휴식도 이 한도를 함께 씁니다.</p>`:'';
 const host=`<div class="stage-host"><img src="./assets/v95/nox.webp" alt="기억 등불의 여주인 녹스"><div><strong>녹스 · ${stage.name} 정비소</strong><p>“${quote}”</p></div></div>${riskNote}`;
 const next=`${hasGimmicks(s)?`${s.firstRun?.enabled?`<details class="stage-gimmick-brief"><summary>녹스의 다음 길 안내 · 펼쳐 보기</summary><p>${STAGE_GIMMICK_PLANS[index]}</p></details>`:`<aside class="stage-gimmick-brief"><strong>녹스의 다음 길 안내</strong><p>${STAGE_GIMMICK_PLANS[index]}</p></aside>`}`:''}<p class="stage-next">다음은 <b>${STAGES[index+1].name}</b>. 그곳까지 내려가면 메아리가 ${echoFadeEvery({...s,memory:Math.max(s.memory,index+1)})}턴마다 1씩 옅어집니다. 준비 중에도 이미 남긴 소리는 사라지지 않습니다.</p>`;
 if(ready)return `${host}<div class="stage-ready"><strong>✓ ${choiceName[s.stagePrepared[index]]} 완료</strong><p>주머니 ${poolSize(s)}개 · 휴대 보급 ${s.provisions}개. 새 기억은 다음 주머니 순환부터 나올 수 있습니다.</p></div>${next}${keyOfferMarkup(s)}${artifactShopMarkup(s)}<p class="ability-reading-note">정비소의 준비는 한 번뿐입니다. 원한다면 남은 기술로 추가 교역을 한 번 할 수 있습니다.</p><div class="modal-actions"><button class="keyword-button" data-act="market" ${s.stageTrades[index]?'disabled':''}>${s.stageTrades[index]?'추가 교역 완료':'녹스와 추가 교역 · 1회'}</button><button class="keyword-button" data-act="stagePlan">원정 계획</button><button class="large-button" data-act="close">던전으로 · 다음 구역으로 →</button></div>`;
 if(recruit)return `<p class="ability-reading-note">이번 정비에서 새 기억 <b>하나</b>를 고릅니다. 지금 손의 힘은 바뀌지 않고 식은 메달과 함께 주머니로 갑니다.</p><div class="stage-offers">${stageOffers(s,index).map(id=>`<button class="stage-offer" data-act="prepare" data-choice="recruit" data-id="${id}">${tokenMarkup(id,{size:70})}<strong>${CARDS[id].name}</strong>${abilityEffectsMarkup(id)}${abilityNotesMarkup(id)}<em>${memoryLore(id,CARDS[id])}</em><span>이 기억과 함께 가기</span></button>`).join('')}</div><div class="modal-actions"><button class="keyword-button" data-act="stageCamp">준비 종류 다시 고르기</button></div>`;
 return `${host}<p class="ability-reading-note"><b>이번 정비에서 한 가지만 선택하세요.</b> 능력 보강·주머니 정리·보급 중 무엇이 다음 구역에 필요한가요?</p><div class="stage-services"><button data-act="stageRecruit">${itemMarkup('lantern',44)}<span><strong>새 기억 영입</strong><small>제시된 능력 3개 중 1개를 주머니에 추가</small></span></button><button data-act="prepare" data-choice="refine" ${poolSize(s)<=5?'disabled':''}>${itemMarkup('shrine',44)}<span><strong>불필요한 기억 정리</strong><small>능력 1개를 골라 영구 제거 · 최소 5개 유지</small></span></button><button data-act="prepare" data-choice="resupply">${itemMarkup('chest',44)}<span><strong>몸을 추스르고 보급 확보</strong><small>체력 +${healingAmount(s,hasRisk(s)?RISK.prepareHeal:6)} · 경계 −2 · 휴대 보급 +1</small></span></button></div>${next}`;
}
export function stagePlanMarkup(s){return `${hasRisk(s)?`<p class="risk-rule-note">${healingNote(s)}. 보급 최대${RISK.heal} · 정비/휴식 최대${RISK.campHeal}. 회복 메달도 함께 계산합니다.</p>`:''}<p class="ability-reading-note">목표는 심층의 <b>용의 기억</b>을 입구로 가져오는 것. 층 사이 세 정비소에서 능력 풀과 보급을 준비합니다. 얕은 층에서는 목표 유물을 얻을 수 없습니다.</p>${stageTrackMarkup(s)}<div class="stage-plan">${STAGES.map((stage,i)=>`<article class="${i===stageIndex(s)?'current':''}"><h3 style="color:${stage.color}">${i+1}. ${stage.name} · ${stage.title}</h3><p>${hasGimmicks(s)?(i===0?stage.description:STAGE_GIMMICK_PLANS[i-1]):stage.description}</p><small>${i<3?s.stagePrepared[i]?'✓ '+choiceName[s.stagePrepared[i]]+' 완료':'정비: 기억 영입 / 1개 정리 / 보급 중 선택':'목표: 용의 기억 회수 → 입구에서 탈출'}</small></article>`).join('')}</div><p class="ability-reading-note">현재 주머니 ${poolSize(s)}개 · 휴대 보급 ${s.provisions}개. ${healingNote(s)} 보급은 턴마다 한 번 체력 최대${hasRisk(s)?RISK.heal:6}을 회복하지만 기본 소리3을 냅니다. 정비소의 추가 교역은 각각 한 번입니다.</p><p class="ability-reading-note">깊이 갈수록 메아리가 오래 남습니다. 심층 귀환 승강기는 기술3·기본 소리8로 상층 정비소와 이어지며, 열린 통로로 추적과 숨결도 지납니다.</p>`;}
export function stageChoiceLines(action){
 if(action.choice==='recruit')return [['녹스',memoryLore(action.id,CARDS[action.id])],['깜부기','식은 기억들 곁에 넣어 둬. 다시 불빛을 받을 때 네 손을 빌릴 거야.'],['녹스','앞의 길뿐 아니라 돌아올 길에도 써 줘. 네 결말은 여기서 듣고 싶으니까.']];
 if(action.choice==='resupply')return [['녹스','따뜻한 것부터 먹어. 아래에서는 이 꾸러미를 풀면 돼.'],['깜부기','포장 풀리는 소리도 금고는 들어. 어디서 쓸지 보고 꺼내.']];
 return [['녹스','놓아주었구나. 가벼워진 만큼 네가 기다리던 손을 더 빨리 만날 거야.'],['깜부기','그 기억이 맡던 일을 다른 메달이 해 줄 수 있는지도 봐.']];
}
